INSERT INTO feature VALUES('presentation-rule-decision','rules','The kernel decides a presentation''s rules by replay','rule-coincidence','implemented','uncommon','dependent provers','A theory block''s rules reach the kernel in the Theory value with their orientation and every derived rule beside the peak it joins; at admission and readmission the kernel replays each orientation against the stated terminating order and each derived rule as the joining of its peak, and refuses a presentation that offers a rule it cannot replay, so no presentation is admitted on the producer''s word.','kernel-term kernel-core','crates/surface-corpus/src/kernel_export.rs::kernel_presentation_readmission corpus/model/data/rule-equation.gandr','corpus/model/data/rule-equation.gandr',NULL);
